values ('ap_physics_2', 11, '11.8', array['11.8']::text[], 'list_sequence', 'Discharging capacitor: initial to final state', 'How a charged capacitor behaves from the start of discharge until steady state.', '[{"label": "Immediately after discharge begins", "meaning": "Charge on the plates and stored energy begin to decrease"}, {"label": "While discharging", "meaning": "Capacitor charge, potential difference, and branch current all decrease toward steady state"}, {"label": "After a long time (t >> τ)", "meaning": "Capacitor and its branch may be modeled with steady-state conditions"}]'::jsonb, NULL, 'Describe these states qualitatively; no mathematical model with respect to time is expected.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-physics-2-reference-u9-u11-2026-10-10; candidate=ap_physics_2-u11-r1-038; ced=11.8.B.2.v; 11.8.B.2.vi; 11.8.B.2.vii')
